using namespace std;

int main() {
    double x1, y1, r1, x2, y2, r2;
    cin >> x1 >> y1 >> r1 >> x2 >> y2 >> r2;

    double dx = x1 - x2;
    double dy = y1 - y2;
    double d = sqrt(dx*dx + dy*dy);

    if (d > r1 + r2) {
        // No intersection, separate
        cout << 4 << endl;
    } else if (abs(d - (r1 + r2)) < 1e-9) {
        // Externally tangent (circumscribed)
        cout << 3 << endl;
    } else if (abs(d - abs(r1 - r2)) < 1e-9) {
        // Internally tangent (inscribed)
        cout << 1 << endl;
    } else if (d < abs(r1 - r2)) {
        // One contains the other without touching
        cout << 0 << endl;
    } else {
        // Two intersection points
        cout << 2 << endl;
    }

    return 0;
}

