import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long x1 = fs.nextLong();
        long y1 = fs.nextLong();
        long r1 = fs.nextLong();
        long x2 = fs.nextLong();
        long y2 = fs.nextLong();
        long r2 = fs.nextLong();

        long dx = x1 - x2;
        long dy = y1 - y2;
        long d2 = dx * dx + dy * dy;

        long sum = r1 + r2;
        long diff = Math.abs(r1 - r2);

        long sum2 = sum * sum;
        long diff2 = diff * diff;

        int ans;
        if (d2 > sum2) {
            ans = 4; // separate
        } else if (d2 == sum2) {
            ans = 3; // externally tangent
        } else if (d2 > diff2) {
            ans = 2; // intersect at two points
        } else if (d2 == diff2) {
            ans = 1; // internally tangent
        } else {
            ans = 0; // one contains the other
        }

        System.out.println(ans);
    }
}
